import{at as e,it as t,n,vt as r}from"./chunks/framework.CsjHfu6k.js";var i=JSON.parse(`{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1792939073000}`),a={name:`faq.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h1><h2 id="q-我安装了一个模块-然后启动时卡在了开机动画。求助" tabindex="-1">Q: 我安装了一个模块，然后启动时卡在了开机动画。求助 <a class="header-anchor" href="#q-我安装了一个模块-然后启动时卡在了开机动画。求助" aria-label="Permalink to “Q: 我安装了一个模块，然后启动时卡在了开机动画。求助”">​</a></h2><p>Magisk 内置了启动循环保护：如果您的设备连续<strong>两次</strong>未能完成启动（<code>boot_completed</code>），Magisk 将在下次启动时自动进入<strong>安全模式</strong>，禁用所有模块（在每个模块文件夹中创建 <code>disable</code> 文件）并禁用 Zygisk，以便您的设备能够正常启动。</p><p>如果您的设备在自动启动循环检测来得及恢复之前就卡住了，或者您想手动恢复：</p><ul><li>如果在开发人员选项中启用了USB调试，请将手机连接到 PC。如果检测到了设备（通过 <code>adb devices</code> 检查），请进入 ADB shell 并运行命令 <code>magisk --remove-modules</code>。这将删除所有模块并自动重新启动设备。</li><li>如果您的设备仍能启动到 Android，您也可以直接在 Magisk app 主屏幕顶部的重新启动菜单（电源图标）中切换<strong>安全模式</strong>，然后重新启动。</li></ul><div class="tip custom-block"><p class="custom-block-title">译者提示</p><p>如果您不知道什么是 ADB shell ，那么请在电脑上直接运行以下命令</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> magisk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --remove-modules</span></span></code></pre></div><p>如果您还不知道什么是 ADB ，那么请查看<a href="https://developer.android.google.cn/studio/command-line/adb?hl=zh-cn" target="_blank" rel="noreferrer">《Android 调试桥 (adb)》</a></p></div><p>如果您没有启用 USB 调试功能且设备无法启动，那么您可以使用安全模式组合键来启动设备，这将使 Magisk 在模块目录中创建一个名为 <code>disable</code> 的空文件，以便在下次使用 Magisk 启动时禁用模块。大多数现代 Android 设备都支持在启动时通过特殊的组合键进入系统的安全模式作为紧急选项，但<strong>请注意</strong>，Magisk 的组合键检测发生在系统检测<strong>之前</strong>，因此许多在线指南中指示的组合键的时间可能需要调整，以激活 Magisk 的安全模式。（可能激活了系统的安全模式而没有激活 Magisk 的安全模式，反之亦然。）</p><p>以下细节应确保模块被正确禁用：</p><ol><li>许多在线指南中提到，进入安全模式时要“当动画标志出现时，按住音量减小键直到系统启动”或类似的说法。然而，这对于 Magisk 检测来说可能<strong>已经太晚</strong>，导致系统安全模式被激活，但模块没有被禁用。</li><li>在动画开始前几秒钟按下音量减小键，并在动画出现后立即释放，这样可以激活 Magisk 的安全模式而不激活系统的安全模式（从而避免禁用其他设备和应用程序设置），然后设备将正常启动，但模块被禁用。</li><li>在动画开始前几秒钟按下音量减小键，并一直按住直到系统启动，这样既可以激活 Magisk 的安全模式，也可以激活系统的安全模式。接下来，在重新启动到正常系统后，模块将被禁用。</li></ol><h2 id="q-为什么-xxx应用会检测到-root" tabindex="-1">Q: 为什么 XXX应用会检测到 Root？ <a class="header-anchor" href="#q-为什么-xxx应用会检测到-root" aria-label="Permalink to “Q: 为什么 XXX应用会检测到 Root？”">​</a></h2><p>Magisk 不再处理 Root 隐藏。有大量 Magisk/Zygisk 模块专门提供这些功能，请在网络上查找它们。😉（您可以在“酷安”或者“哔哩哔哩”中搜索）</p><p>比较流行的模块是 <a href="https://github.com/LSPosed/LSPosed.github.io/releases/latest" target="_blank" rel="noreferrer">Shamiko</a> 。</p><div class="warning custom-block"><p class="custom-block-title">警告</p><p>如果你使用的是「<a href="https://huskydg.github.io/magisk-files/" target="_blank" rel="noreferrer">Magisk Delta</a>」，则<a href="https://huskydg.github.io/magisk-files/docs/faq.html#should-i-install-shxxxxo-module-to-hide-root" target="_blank" rel="noreferrer">无法使用</a>此模块！</p></div><h2 id="q-如何在模拟器中使用-magisk" tabindex="-1">Q: 如何在模拟器中使用 Magisk？ <a class="header-anchor" href="#q-如何在模拟器中使用-magisk" aria-label="Permalink to “Q: 如何在模拟器中使用 Magisk？”">​</a></h2><p>在模拟器运行并可通过 ADB 访问时，运行 <code>./build.py emulator [Magisk APK 的路径]</code>（或 <code>./build.py emulator -b</code> 从源代码构建并安装）即可在正在运行的模拟器上临时启动 Magisk。此运行时设置不会在冷重启后保留，因此如果需要模拟重启，请重新执行该命令。</p><p>要在 Android 虚拟设备（AVD）上持久安装，您可以使用 <code>./build.py patch --avd &lt;path/to/ramdisk.img&gt; [output]</code> 直接在主机上修补其 <code>ramdisk.img</code>。</p><p>这些命令已在 Android Studio 附带的官方 Android 虚拟设备（AVD）上测试；其他模拟器可能也可以使用，但模拟器必须启用 SELinux。</p><h2 id="q-为什么这个文档很多错误或者不通顺的地方" tabindex="-1">Q: 为什么这个文档很多错误或者不通顺的地方 <a class="header-anchor" href="#q-为什么这个文档很多错误或者不通顺的地方" aria-label="Permalink to “Q: 为什么这个文档很多错误或者不通顺的地方”">​</a></h2><p>这个文档本质上还是机器翻译的，然而机器翻译的正确率有待提高。如果您发现了这些错误或者不通顺的地方，希望您可以向我们<a href="https://gitee.com/Jesse205/magisk-chinese-document/issues" target="_blank" rel="noreferrer">提交反馈</a>。</p><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to “参考链接”">​</a></h2><ul><li><a href="https://topjohnwu.github.io/Magisk/faq.html" target="_blank" rel="noreferrer">Magisk Frequently Asked Questions</a>（官方）</li></ul>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};